INSERT INTO `appentries` VALUES (7,'Supply and Delivery of Medical Equipment for the Municipal Health Office','Procurement of diagnostic and treatment equipment for the Rural Health Unit, including patient monitors, nebulisers, an ECG machine and examination furniture, to restore full service capacity at the main health station.',NULL,'PAP-HLTH-2024-011',NULL,'Goods','competitiveBidding',2850000.00,NULL,NULL,'General Fund â€” 20% Development Fund',NULL,'Q1','Q3',NULL,2026,'locked','finalApp','2026-01-29 03:20:00',NULL,NULL,NULL,NULL,'2026-08-05 19:12:44','2026-08-05 19:12:44',12,10,NULL,7,'final',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(8,'Concreting of Barangay San Vicente Farm-to-Market Road (Phase 1)','Concreting of 1.2 kilometres of farm-to-market road serving four upland barangays, including drainage canals and road shoulders, to reduce haulage cost for local produce.',NULL,'PAP-INFR-2024-004',NULL,'Infrastructure','competitiveBidding',8400000.00,NULL,NULL,'Local Development Fund',NULL,'Q1','Q2',NULL,2026,'locked','finalApp','2026-01-30 03:20:00',NULL,NULL,NULL,NULL,'2026-08-05 19:12:44','2026-08-05 19:12:44',11,11,NULL,7,'final',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(9,'Construction of Barangay Malitbog Health Station','Construction of a one-storey barangay health station with consultation rooms, a birthing area, a pharmacy counter and a potable water system.',NULL,'PAP-HLTH-2024-019',NULL,'Infrastructure','competitiveBidding',4200000.00,NULL,NULL,'General Fund â€” 20% Development Fund',NULL,'Q2','Q4',NULL,2026,'locked','finalApp','2026-01-31 03:20:00',NULL,NULL,NULL,NULL,'2026-08-05 19:12:44','2026-08-05 19:12:44',12,10,NULL,7,'final',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(10,'Supply and Delivery of Information Technology Equipment for Municipal Offices','Procurement of desktop computers, network switches and uninterruptible power supplies to replace end-of-life units across the Municipal Hall, in support of the digitalisation programme.',NULL,'PAP-ITO-2024-007',NULL,'Goods','competitiveBidding',1950000.00,NULL,NULL,'General Fund â€” MOOE',NULL,'Q3','Q4',NULL,2026,'locked','finalApp','2026-02-01 03:20:00',NULL,NULL,NULL,NULL,'2026-08-05 19:12:44','2026-08-05 19:12:44',13,12,NULL,7,'final',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(11,'Procurement of Two (2) Units Garbage Compactor Truck','Acquisition of two garbage compactor trucks to expand solid waste collection coverage to the remaining eight barangays under the Ecological Solid Waste Management Plan.',NULL,'PAP-GSO-2024-002',NULL,'Goods','competitiveBidding',11500000.00,NULL,NULL,'General Fund â€” Capital Outlay',NULL,'Q4','Q4',NULL,2026,'locked','finalApp','2026-02-02 03:20:00',NULL,NULL,NULL,NULL,'2026-08-05 19:12:44','2026-08-05 19:12:44',10,13,NULL,7,'final',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(12,'Construction of Municipal Evacuation Center','Construction of a disaster-resilient evacuation centre with a capacity of 500 persons, including sanitation facilities, a generator set and a rainwater collection system.',NULL,'PAP-INFR-2024-021',NULL,'Infrastructure','competitiveBidding',15750000.00,NULL,NULL,'Local Disaster Risk Reduction and Management Fund',NULL,'Q4','Q4',NULL,2026,'locked','finalApp','2026-02-03 03:20:00',NULL,NULL,NULL,NULL,'2026-08-05 19:12:44','2026-08-05 19:12:44',11,11,NULL,7,'final',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(13,'Road concreting materials and equipment rental',NULL,NULL,NULL,NULL,NULL,'competitiveBidding',4000000.00,NULL,NULL,NULL,NULL,'Q1','Q2',NULL,2031,'locked','finalApp','2026-08-05 19:13:17',NULL,NULL,NULL,NULL,'2026-08-05 19:13:17','2026-08-05 19:13:17',11,15,9,7,'final',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(14,'Road signage and markings',NULL,NULL,NULL,NULL,NULL,'competitiveBidding',200000.00,NULL,NULL,NULL,NULL,'Q2','Q3',NULL,2031,'cancelled','finalApp','2026-08-05 19:13:18',NULL,'Project deferred to next year; signage folded into the main contract.',NULL,'2026-08-05 19:13:18','2026-08-05 19:13:18','2026-08-05 19:13:18',11,15,9