INSERT INTO `documenttemplates` VALUES (1,'notice-of-award-standard','Notice of Award (standard)','noticeOfAward','Issued to the winning bidder once the Mayor has approved the award.','active',1,1,1,'2026-08-11 14:26:20','2026-08-11 14:29:39',NULL),(2,'notice-to-proceed-standard','Notice to Proceed (standard)','noticeToProceed','Starts contract time. Contract days are counted from its effectivity.','active',2,1,1,'2026-08-11 14:26:20','2026-08-11 14:26:20',NULL),(3,'contract-agreement-standard','Contract Agreement (standard)','contractAgreement','The agreement between the municipality and the supplier.','active',3,1,1,'2026-08-11 14:26:20','2026-08-11 14:26:20',NULL),(4,'purchase-request-form','Purchase Request form','purchaseRequest','The requisition with its certification and approval boxes.','active',4,0,1,'2026-08-11 14:26:20','2026-08-11 14:26:20',NULL),(5,'inspection-acceptance-report','Inspection and Acceptance Report','inspectionAcceptanceReport','Records what was delivered, inspected and accepted.','active',5,0,1,'2026-08-11 14:26:20','2026-08-11 14:26:20',NULL),(6,'certificate-of-recognition','Certificate of Recognition','certificateOfRecognition','Recognises an individual or organisation\'s contribution.','active',6,0,1,'2026-08-11 14:26:20','2026-08-11 14:26:20',NULL),(7,'certificate-of-participation','Certificate of Participation','certificateOfParticipation','Confirms attendance or participation in an activity.','active',7,0,1,'2026-08-11 14:26:20','2026-08-11 14:26:20',NULL),(8,'certificate-of-appreciation','Certificate of Appreciation','certificateOfAppreciation','Thanks a person or body for their support.','active',8,0,1,'2026-08-11 14:26:20','2026-08-11 14:26:20',NULL),(9,'invitation-to-bid-standard','Invitation to Bid (standard)','invitationToBid','The official invitation for a published solicitation. The public-friendly posting is written separately as an announcement.','active',14,1,1,'2026-08-12 03:14:35','2026-08-12 03:17:40',NULL);
