INSERT INTO `generateddocuments` VALUES (1,'NOA-2026-0001','noticeOfAward','NOA-2026-0001 â€” Supply and Delivery of Medical Equipment for the Municipal Health Office','award',1,'<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><title>NOA-2026-0001 â€” Supply and Delivery of Medical Equipment for the Municipal Health Office</title>\n<style>\n  *, *::before, *::after { box-sizing: border-box; }\n  body {\n    margin: 0;\n    /* Explicit white. With printBackground on, a transparent body inherits\n       whatever is behind it â€” fine on paper, wrong everywhere the same HTML is\n       previewed, including a dark-themed browser. (No backticks in here: this\n       block lives inside a template literal.) */\n    background: #ffffff;\n    font-family: \"Times New Roman\", Times, serif;\n    font-size: 12pt;\n    line-height: 1.5;\n    color: #000;\n  }\n  h1, h2, h3, h4 { margin: 0 0 8pt; line-height: 1.25; }\n  p { margin: 0 0 8pt; }\n  table { border-collapse: collapse; width: 100%; }\n  /* Tables in official documents are ruled. An unruled table reads as a\n     layout accident rather than a schedule of items. */\n  table.doc-table th, table.doc-table td {\n    border: 1px solid #000;\n    padding: 4pt 6pt;\n    font-size: 10.5pt;\n  }\n  table.doc-table th { background: #eee; text-align: center; }\n  /* A signature block split across a page break is the single most common\n     complaint about generated documents. */\n  .signature-block, .sig, tr { page-break-inside: avoid; }\n  img { max-width: 100%; }\n</style>\n</head><body>\n<div style=\"text-align:center; margin-bottom:18pt\">\n  <div style=\"font-size:10.5pt\">Republic of the Philippines</div>\n  <div style=\"font-size:12pt; font-weight:bold; text-transform:uppercase\">Municipality of Roxas, Oriental Mindoro</div>\n  <div style=\"font-size:10pt\">Municipal Hall Compound, Poblacion, Roxas, Oriental Mindoro</div>\n  <hr style=\"border:0; border-top:1.5px solid #000; margin-top:8pt\" />\n</div>\n<p style=\"text-align:right\">August 11, 2026</p>\n<p style=\"margin-top:14pt\"><strong>Medline Diagnostics Trading Corporation</strong><br />142 Roxas Boulevard, Calapan City, Oriental Mindoro</p>\n<p>Attention: <strong></strong></p>\n<h2 style=\"text-align:center; margin:20pt 0 4pt; letter-spacing:1px\">NOTICE OF AWARD</h2>\n<p style=\"text-align:center; margin-bottom:18pt\">NOA-2026-0001</p>\n<p>Sir/Madam:</p>\n<p style=\"text-align:justify\">We are pleased to inform you that following the evaluation conducted by the Bids and Awards Committee under\n<strong>ITB-2026-001</strong> for <strong>Supply and Delivery of Medical Equipment for the Municipal Health Office</strong>, with an Approved Budget for the Contract of â‚±2,850,000.00,\nyour bid has been determined to be the .</p>\n<p style=\"text-align:justify\">The contract is hereby awarded to your firm in the total amount of\n<strong>TWO MILLION SEVEN HUNDRED THREE THOUSAND FIVE HUNDRED PESOS AND 00/100 (â‚±2,703,500.00)</strong>, procured through Competitive Bidding pursuant to IRR Sec. 26.</p>\n<p style=\"text-align:justify\">You are required to formally enter into contract with the Municipality of Roxas, Oriental Mindoro and to post the required\nperformance security within ten (10) calendar days from your receipt of this Notice.</p>\n\n<div class=\"signature-block\" style=\"margin-top:42pt\">\n  <div>Very truly yours,</div>\n  <div style=\"margin-top:36pt; font-weight:bold; text-transform:uppercase\">Hon. Teresita M. Alcantara</div>\n  <div>Municipal Mayor</div>\n</div>\n<div style=\"margin-top:34pt; border-top:1px solid #000; padding-top:6pt\">\n  <div style=\"font-size:10.5pt\">Conforme:</div>\n  <div style=\"margin-top:26pt; font-weight:bold\"></div>\n  <div style=\"font-size:10.5pt\">Medline Diagnostics Trading Corporation &nbsp;Â·&nbsp; Date: ______________</div>\n</div></body></html>','{\"abc\": \"â‚±2,850,000.00\", \"lgu_name\": \"Municipality of Roxas, Oriental Mindoro\", \"pr_number\": \"PR-2026-0001\