--
-- Table structure for table `securityalerts`
--

DROP TABLE IF EXISTS `securityalerts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `securityalerts` (
  `id` int NOT NULL AUTO_INCREMENT,
  `type` enum('recordModifiedOutsideSystem','recordInsertedOutsideSystem','recordDeletedOutsideSystem','auditChainBroken','repeatedLoginFailures','repeatedMfaFailures','privilegeChanged','credentialReset','offHoursAccess','bulkDocumentAccess','duplicateBidDocument','bidIpClustering','amountChangedAfterApproval') NOT NULL,
  `severity` enum('critical','high','medium','low') NOT NULL DEFAULT 'medium',
  `summary` varchar(500) NOT NULL,
  `detail` json DEFAULT NULL,
  `entityRef` varchar(64) DEFAULT NULL,
  `entityId` int DEFAULT NULL,
  `dedupeKey` varchar(200) NOT NULL,
  `occurrences` int NOT NULL DEFAULT '1',
  `lastSeenAt` datetime NOT NULL,
  `status` enum('open','acknowledged','resolved','dismissed') NOT NULL DEFAULT 'open',
  `resolutionNote` text,
  `resolvedAt` datetime DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `resolvedById` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `security_alerts_dedupe_key` (`dedupeKey`),
  KEY `security_alerts_status` (`status`),
  KEY `security_alerts_severity` (`severity`),
  KEY `security_alerts_type` (`type`),
  KEY `resolvedById` (`resolvedById`),
  CONSTRAINT `securityalerts_ibfk_1` FOREIGN KEY (`resolvedById`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `securityalerts_ibfk_2` FOREIGN KEY (`resolvedById`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=58 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `securityalerts`
--

LOCK TABLES `securityalerts` WRITE;
/*!40000 ALTER TABLE `securityalerts` DISABLE KEYS */;
