  `organizationType` enum('corporation','partnership','soleProprietorship','cooperative') NOT NULL DEFAULT 'corporation',
  `isJointVenture` tinyint(1) NOT NULL DEFAULT '0',
  `isForeignBidder` tinyint(1) NOT NULL DEFAULT '0',
  `philgepsRegistrationNo` varchar(255) DEFAULT NULL,
  `philgepsExpiry` date DEFAULT NULL,
  `isVatRegistered` tinyint(1) NOT NULL DEFAULT '1',
  `taxClassification` enum('goods','services') NOT NULL DEFAULT 'goods',
  `contactEmail` varchar(255) DEFAULT NULL,
  `contactPerson` varchar(255) DEFAULT NULL,
  `contactPhone` varchar(255) DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `referenceCode` varchar(24) DEFAULT NULL,
  `registrationStatus` enum('draft','submitted','verified','returned','blacklisted') NOT NULL DEFAULT 'draft',
  `reviewRemarks` text,
  `submittedAt` datetime DEFAULT NULL,
  `reviewedAt` datetime DEFAULT NULL,
  `receivedAt` datetime DEFAULT NULL,
  `accountCreatedAt` datetime DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `userId` int DEFAULT NULL,
  `reviewedByUserId` int DEFAULT NULL,
  `recordedByUserId` int DEFAULT NULL,
  `announcementId` int DEFAULT NULL,
  `blacklistedAt` datetime DEFAULT NULL,
  `blacklistedUntil` datetime DEFAULT NULL,
  `blacklistGrounds` text,
  `blacklistOrderNo` varchar(255) DEFAULT NULL,
  `statusBeforeBlacklist` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `referenceCode` (`referenceCode`),
  UNIQUE KEY `referenceCode_2` (`referenceCode`),
  UNIQUE KEY `referenceCode_3` (`referenceCode`),
  UNIQUE KEY `referenceCode_4` (`referenceCode`),
  UNIQUE KEY `referenceCode_5` (`referenceCode`),
  UNIQUE KEY `referenceCode_6` (`referenceCode`),
  UNIQUE KEY `referenceCode_7` (`referenceCode`),
  UNIQUE KEY `referenceCode_8` (`referenceCode`),
  UNIQUE KEY `referenceCode_9` (`referenceCode`),
  KEY `userId` (`userId`),
  KEY `reviewedByUserId` (`reviewedByUserId`),
  KEY `recordedByUserId` (`recordedByUserId`),
  KEY `announcementId` (`announcementId`),
